package vn.iotstar.service.impl; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import vn.iotstar.entity.OtpToken; import vn.iotstar.repository.OtpTokenRepository; import vn.iotstar.service.*; import java.security.SecureRandom; import java.time.*; @Service @RequiredArgsConstructor public class OtpServiceImpl implements OtpService{private static final int MAX=5;private final OtpTokenRepository repo;private final PasswordEncoder encoder;private final EmailService email;private final SecureRandom random=new SecureRandom();private String otp(){return "%06d".formatted(random.nextInt(1000000));}@Transactional public void sendRegisterOtp(String e){send(e,"REGISTER","Shop - Xác nhận đăng ký tài khoản");}@Transactional public void sendResetPasswordOtp(String e){send(e,"RESET_PASSWORD","Shop - OTP đặt lại mật khẩu");}private void send(String e,String type,String subject){repo.deleteByEmailAndType(e,type);String o=otp();repo.save(OtpToken.builder().email(e).otpHash(encoder.encode(o)).type(type).expiresAt(LocalDateTime.now().plusMinutes(5)).attempts(0).used(false).createdAt(LocalDateTime.now()).build());email.sendOtp(e,o,subject);}private boolean verify(String e,String o,String type){OtpToken t=repo.findTopByEmailAndTypeAndUsedFalseOrderByCreatedAtDesc(e,type).orElse(null);if(t==null||t.getExpiresAt().isBefore(LocalDateTime.now())||t.getAttempts()>=MAX)return false;t.setAttempts(t.getAttempts()+1);if(!encoder.matches(o,t.getOtpHash())){repo.save(t);return false;}t.setUsed(true);repo.save(t);return true;}public boolean verifyRegisterOtp(String e,String o){return verify(e,o,"REGISTER");}public boolean verifyResetPasswordOtp(String e,String o){return verify(e,o,"RESET_PASSWORD");}}